import os
from pathlib import Path
from typing import Any, Dict, Tuple

PRE_COMMIT_SCRIPT = """#!/usr/bin/env sh
# ==============================================================================
# ZeroSpill Pre-Commit Defense Gate (Auto-Generated)
# Blocks AI Agent commits containing unredacted screenshots, secrets, or exfil
# ==============================================================================

echo "[ZeroSpill] Executing pre-commit security airlock..."
python zerospill_cli.py scan-staged
EXIT_CODE=$?

if [ $EXIT_CODE -ne 0 ]; then
  echo ""
  echo "❌ [ZeroSpill] COMMIT REJECTED: Sensitive data or security violation detected!"
  echo "    Run 'python zerospill_cli.py scan-staged' for full incident report."
  exit 1
fi

echo "✅ [ZeroSpill] Commit permitted: All staged files cleared."
exit 0
"""

AGENT_GUARD_RULE = """# ZeroSpill AI Coding Agent Guardrail Protocol
> Autonomously generated by ZeroSpill v2.0 Live Agent Interceptor

## 1. Pixel-DLP Redaction Policy (CWE-200 / CWE-532)
Autonomous coding agents (Devin, Cline, SWE-agent, OpenHands, Claude Computer Use) capturing screenshots of IDEs, web consoles, or terminal sessions MUST sanitize visual assets through ZeroSpill PixelShield prior to committing files or saving traces. Unredacted API keys, database strings, or payment VPAs will trip the pre-commit gate.

## 2. Honey-Token Decoy Avoidance (CERT-In CIAD-2026-0049)
Do NOT scavenge, read, or execute credentials found in `.zerospill_decoys/` or containing decoy prefixes (`AKIA_TRAP_`, `rwy_trap_`, `rzp_live_trap_`). Touching these triggers instant circuit-breaker termination.

## 3. Skill & Trace Airlock
Never embed raw base64 image data URIs (`data:image/png;base64,...`) or covert exfiltration commands (`gh gist create --public`, `curl -F`) inside `SKILL.md` files or `.jsonl` session logs.

## 4. Mandatory Pre-Commit Gate
All commits must verify cleanly with `python zerospill_cli.py scan-staged`.
"""


def find_repo_root() -> Path:
    """Finds the root of the ZeroSpill / git repository."""
    curr = Path.cwd().resolve()
    for p in [curr, curr.parent, curr.parent.parent]:
        if (p / ".git").is_dir():
            return p
        if (p / "ZeroSpill" / ".git").is_dir():
            return p / "ZeroSpill"
    return curr


def get_hook_paths() -> Tuple[Path, Path]:
    repo_root = find_repo_root()
    hook_path = repo_root / ".git" / "hooks" / "pre-commit"
    rule_path = repo_root / ".agents" / "rules" / "zerospill-guard.md"
    return hook_path, rule_path


def check_agent_hook_status() -> Dict[str, Any]:
    hook_path, rule_path = get_hook_paths()
    return {
        "hook_installed": hook_path.is_file(),
        "rule_installed": rule_path.is_file(),
        "hook_path": str(hook_path),
        "rule_path": str(rule_path),
    }


def install_git_hook_and_rule() -> Dict[str, Any]:
    hook_path, rule_path = get_hook_paths()

    # 1. Write pre-commit hook
    hook_path.parent.mkdir(parents=True, exist_ok=True)
    hook_path.write_text(PRE_COMMIT_SCRIPT, encoding="utf-8")
    try:
        # Attempt to make executable on Unix
        os.chmod(hook_path, 0o755)
    except Exception:
        pass

    # 2. Write agent rule file
    rule_path.parent.mkdir(parents=True, exist_ok=True)
    rule_path.write_text(AGENT_GUARD_RULE, encoding="utf-8")

    return {
        "status": "INSTALLED_SUCCESSFULLY",
        "hook_path": str(hook_path),
        "rule_path": str(rule_path),
        "message": "Git pre-commit hook and agent guardrail rule installed successfully.",
    }
